## Contrat scientifique de cette exécution

- uniquement `train`, `validation` et `calibration` synthétiques ; aucun split `test` ;
- ancien format arabe et format unifié 2026 arabe/latin présents dans chaque split ;
- refus de toute régression sur l'un des deux formats, puis sélection sur exact-match validation et CER en cas d'égalité ; calibration exclue de la sélection ;
- configuration officielle Arabic PP-OCRv5 et dictionnaire officiel de 747 caractères, tous deux gelés sur PaddleOCR `v3.7.0` ;
- le dossier Drive cible ne doit pas exister : aucune exécution antérieure n'est écrasée ;
- les métriques synthétiques ne prouvent aucune précision sur photo réelle ;
- E2 entraîne seulement le recognizer sur des crops de plaque : le détecteur séparé reste obligatoire avant OCR ;
- statut attendu : `synthetic_e2_complete_not_qualified`, intégration SaaS interdite.

#@title 1. Monter Drive, vérifier le GPU et geler les paramètres
from google.colab import drive
drive.mount('/content/drive')

from pathlib import Path
import hashlib, json, os, shutil, subprocess, sys, urllib.request, zipfile
import torch

assert torch.cuda.is_available(), 'Sélectionnez Exécution > Modifier le type d’exécution > GPU.'
SEED = 20260825 #@param {type:'integer'}
TRAIN_GROUPS = 1024 #@param {type:'integer'}
VALIDATION_GROUPS = 256 #@param {type:'integer'}
CALIBRATION_GROUPS = 256 #@param {type:'integer'}
VARIANTS_PER_GROUP = 3 #@param {type:'integer'}
UNIFIED_FRACTION = 0.5
EPOCHS = 20 #@param {type:'integer'}
BATCH_SIZE = 128 #@param {type:'integer'}
RUN_ID = 'anpr_v2_e2_synthetic_ppocrv5_seed20260825_run01' #@param {type:'string'}
assert SEED == 20260825, 'Cette exécution publiée est préenregistrée avec la graine 20260825.'
assert (TRAIN_GROUPS, VALIDATION_GROUPS, CALIBRATION_GROUPS) == (1024, 256, 256)
assert VARIANTS_PER_GROUP == 3 and UNIFIED_FRACTION == 0.5
assert EPOCHS == 20 and BATCH_SIZE == 128
DRIVE_ROOT = Path('/content/drive/MyDrive/RentFleet_PFE/S7_vehicle_vision_assistant')
DRIVE_OUTPUT = DRIVE_ROOT / 'modeles' / RUN_ID
assert not DRIVE_OUTPUT.exists(), f'Aucun écrasement autorisé: {DRIVE_OUTPUT}'
print({
    'python': sys.version.split()[0], 'torch': torch.__version__,
    'torch_cuda': torch.version.cuda, 'gpu': torch.cuda.get_device_name(0),
    'run_id': RUN_ID, 'drive_output': str(DRIVE_OUTPUT),
    'synthetic_only': True, 'final_test_opened': False,
})
